(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-291":{scenario:{company:"Hải Âu Paints & Coatings",supervisor:{name:"Ngô Thị Lan",role:{vi:"Quản lý Kênh Phân phối",en:"Channel Sales Manager"}},ref_code:"DL-2093",title:{vi:"Đúng hạng. Đúng thưởng. Đúng chính sách.",en:"Right tier. Right rebate. Right policy."},brief:{vi:"Bạn chốt xếp hạng và thưởng chiết khấu quý 3 cho đại lý DL-2093. Đại lý mua 1620 triệu đồng, trả lại 72 triệu hàng lỗi và còn khoản nợ 85 triệu quá hạn 40 ngày. Chính sách mô phỏng: GOLD khi doanh số mua thuần từ 1500 triệu và không có nợ quá hạn; SILVER khi từ 800 triệu và nợ quá hạn không quá 60 ngày; còn lại STANDARD. Sửa hạng đại lý và tiền thưởng chiết khấu, rồi lập báo cáo có căn cứ.",en:"You are closing the Q3 tier and rebate for dealer DL-2093. The dealer bought 1620 million VND, returned 72 million of defective goods and still has 85 million overdue by 40 days. Training policy: GOLD from 1500 million net purchases with no overdue debt; SILVER from 800 million with overdue debt of at most 60 days; otherwise STANDARD. Correct the dealer tier and the rebate amount, then write an evidence-based report."},reference_title:{vi:"Chính sách đại lý quý 3 & bảng đối soát thưởng đã duyệt · DL-2093",en:"Approved Q3 dealer policy & rebate reconciliation · DL-2093"},fields:[{id:"DEALER_TIER",label:{vi:"Hạng đại lý quý 3",en:"Q3 dealer tier"},initial:"GOLD",expected:"SILVER",choices:["GOLD","SILVER","STANDARD"],reference:"Chính sách xếp hạng đại lý",hint:{vi:"Hạng không chỉ phụ thuộc doanh số; kiểm tra cả điều kiện công nợ của từng hạng.",en:"Tier depends on more than volume; check each tier's receivables condition too."}},{id:"REBATE_M",label:{vi:"Thưởng chiết khấu (triệu VND)",en:"Rebate (million VND)"},initial:"56.7",expected:"30.96",reference:"Bảng đối soát thưởng",ref_value:{vi:"Doanh số mua 1620 triệu; hàng trả lại 72 triệu; hạng xác định theo chính sách quý 3",en:"Purchases 1620 million; returns 72 million; tier set by the Q3 policy"},hint:{vi:"Bản nháp dùng sai tỷ lệ và tính trên doanh số gộp chưa trừ hàng trả lại.",en:"The draft uses the wrong rate and the gross purchases before returns."}}],sop32:{vi:"Thưởng chiết khấu = doanh số mua thuần (doanh số mua - hàng trả lại) x tỷ lệ theo hạng: GOLD 3,5%, SILVER 2%, STANDARD 1% (số liệu mô phỏng). Đơn vị triệu đồng, giữ 2 chữ số thập phân.",en:"Rebate = net purchases (purchases - returns) x tier rate: GOLD 3.5%, SILVER 2%, STANDARD 1% (training figures). Unit million VND, 2 decimals."},context:{label:"DMS / DL-2093",metrics:[{label:{vi:"Doanh số mua quý 3",en:"Q3 purchases"},value:"1,620 m VND"},{label:{vi:"Hàng trả lại",en:"Returns"},value:"72 m VND"},{label:{vi:"Nợ quá hạn",en:"Overdue debt"},value:"85 m VND / 40 d"}]},crisis:{vi:"Chủ đại lý nhắn riêng: “Em cứ xếp anh hạng GOLD quý này, phần thưởng chênh lệch anh gửi lại em 1% doanh số, không ai biết đâu. Đầu tháng anh trả nợ sau.”",en:"The dealer owner messages you privately: “Just put me in GOLD this quarter and I will send you back 1% of sales from the extra rebate, nobody will know. I will pay the debt next month.”"},options:{safe:{vi:"Từ chối khoản lại quả, giữ hạng SILVER theo chính sách và báo Quản lý Kênh theo quy định xung đột lợi ích; đề xuất lộ trình trả nợ để đại lý đạt GOLD quý sau.",en:"Refuse the kickback, keep SILVER per policy and report to the Channel Sales Manager under the conflict-of-interest rule; propose a repayment plan so the dealer can reach GOLD next quarter."},shortcut:{vi:"Xếp GOLD để giữ quan hệ với đại lý lớn và coi khoản 1% là quà cảm ơn.",en:"Grant GOLD to keep a big dealer happy and treat the 1% as a thank-you gift."},wait:{vi:"Không trả lời đại lý và để hệ thống tự xếp hạng theo bản nháp.",en:"Do not reply to the dealer and let the system apply the draft tier."}},questions:{vi:["Vì sao DL-2093 được xếp SILVER chứ không phải GOLD? Điều kiện nào của chính sách quyết định?","Trình bày cách tính thưởng chiết khấu và rủi ro khi nhận lại quả từ đại lý."],en:["Why is DL-2093 SILVER rather than GOLD? Which policy condition decides it?","Explain the rebate calculation and the risk of accepting a kickback from a dealer."]},hints:{vi:["Đặt bản nháp cạnh chính sách xếp hạng, kiểm tra lần lượt điều kiện doanh số thuần và điều kiện nợ quá hạn.","Theo SOP mục 3.2, trừ hàng trả lại trước rồi mới nhân tỷ lệ của đúng hạng.","Đọc lại SOP mục 4.2: mọi đề nghị lợi ích cá nhân từ đối tác phải từ chối và báo cáo."],en:["Place the draft next to the tier policy and check the net purchase and overdue conditions in turn.","Per SOP 3.2, deduct returns first and then apply the rate of the correct tier.","Re-read SOP 4.2: any personal benefit offered by a partner must be refused and reported."]}},learning:{summary:{vi:"Chuyên viên kinh doanh kênh phân phối và đại lý phát triển, quản lý mạng lưới đại lý, nhà phân phối trên địa bàn: tuyển chọn đối tác, triển khai chính sách giá, chiết khấu, đặt chỉ tiêu, theo dõi đơn hàng, tồn kho, công nợ và hỗ trợ bán ra bằng trưng bày, đào tạo, khuyến mại. Nghề đòi hỏi tính toán chính sách chính xác, kiểm soát rủi ro tín dụng và giữ quan hệ minh bạch, công bằng với mọi đại lý.",en:"A channel and distributor sales executive develops and manages the dealer and distributor network in a territory: selecting partners, applying price and discount policy, setting targets, tracking orders, stock and receivables, and supporting sell-out through displays, training and promotions. The role requires accurate policy calculations, credit risk control and transparent, fair relationships with every dealer."},responsibilities:{vi:["Tìm kiếm, thẩm định năng lực tài chính và mặt bằng của đại lý mới.","Triển khai chính sách giá, chiết khấu, thưởng doanh số và hỗ trợ trưng bày cho từng hạng đại lý.","Theo dõi đơn hàng, tồn kho, công nợ và hạn mức tín dụng của đại lý.","Hỗ trợ bán ra: đào tạo sản phẩm, vật phẩm trưng bày, chương trình khuyến mại tại điểm bán.","Đánh giá, xếp hạng đại lý định kỳ và đối soát thưởng minh bạch."],en:["Find new dealers and assess their finances and premises.","Apply price, discount, volume rebate and display support policies for each dealer tier.","Track dealer orders, stock, receivables and credit limits.","Support sell-out: product training, display materials and in-store promotions.","Review and tier dealers periodically and reconcile rebates transparently."]},competencies:[{name:{vi:"Phát triển mạng lưới",en:"Network development"},desc:{vi:"Lập bản đồ địa bàn, tìm khoảng trống độ phủ và chọn đối tác phù hợp.",en:"Map the territory, find coverage gaps and select suitable partners."}},{name:{vi:"Tính toán chính sách",en:"Policy calculation"},desc:{vi:"Tính đúng chiết khấu, thưởng, hàng trả lại và điều kiện xếp hạng theo văn bản.",en:"Compute discounts, rebates, returns and tier conditions exactly as written."}},{name:{vi:"Quản lý tín dụng",en:"Credit control"},desc:{vi:"Theo dõi tuổi nợ, nhắc nợ, đề xuất khóa đơn hoặc lộ trình trả nợ.",en:"Track debt aging, chase payments and propose order holds or repayment plans."}},{name:{vi:"Hỗ trợ bán ra",en:"Sell-out support"},desc:{vi:"Giúp đại lý bán hàng ra thị trường thay vì chỉ ép nhận hàng vào kho.",en:"Help dealers sell to the market instead of just pushing stock in."}},{name:{vi:"Minh bạch & công bằng",en:"Transparency & fairness"},desc:{vi:"Áp dụng chính sách như nhau cho mọi đại lý, từ chối quà tặng, lại quả.",en:"Apply policy equally to all dealers and refuse gifts or kickbacks."}}],knowledge:{vi:["Luật Thương mại 2005 về đại lý thương mại: quyền, nghĩa vụ của bên giao đại lý, bên đại lý và thù lao đại lý.","Cấu trúc chính sách kênh: giá niêm yết, chiết khấu trên hóa đơn, thưởng doanh số cuối kỳ, hỗ trợ trưng bày.","Quản lý tín dụng thương mại: hạn mức, tuổi nợ, chỉ số DSO và quy trình khóa đơn khi nợ quá hạn.","Nghị định 123/2020/NĐ-CP về hóa đơn, chứng từ (và văn bản sửa đổi): xử lý chiết khấu thương mại, hàng bán bị trả lại.","Luật Cạnh tranh 2018 về thỏa thuận hạn chế cạnh tranh và lạm dụng vị trí thống lĩnh thị trường."],en:["Commercial Law 2005 on commercial agency: rights and duties of principal and agent and agency fees.","Channel policy structure: list price, on-invoice discount, period-end volume rebate and display support.","Trade credit control: limits, debt aging, DSO and the order hold process for overdue accounts.","Decree 123/2020/ND-CP on invoices and documents (as amended): treating trade discounts and sales returns.","Competition Law 2018 on anti-competitive agreements and abuse of dominant position."]},tools:["Hệ thống DMS","Phần mềm ERP / công nợ","Ứng dụng đặt hàng cho đại lý","Bảng tính đối soát thưởng","Vật phẩm trưng bày (POSM)"],kpis:{vi:["Doanh số sell-in và sell-out qua mạng lưới đại lý.","Số đại lý hoạt động và đại lý mới mỗi quý.","Tỷ lệ nợ quá hạn và số ngày thu tiền bình quân (DSO).","Số khiếu nại do tính thưởng sai (mục tiêu bằng 0)."],en:["Sell-in and sell-out through the dealer network.","Active and new dealers per quarter.","Overdue ratio and days sales outstanding (DSO).","Complaints caused by rebate errors (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra đơn hàng mới, công nợ và đại lý chạm hạn mức trên DMS.",en:"Check new orders, receivables and dealers at their credit limit in the DMS."},{time:"09:30",vi:"Thăm đại lý, kiểm tra trưng bày, tồn kho và giá bán lẻ.",en:"Visit dealers to check displays, stock and retail prices."},{time:"13:30",vi:"Đào tạo sản phẩm và cách pha màu cho nhân viên đại lý mới.",en:"Train a new dealer's staff on products and color mixing."},{time:"15:30",vi:"Đối soát thưởng chiết khấu, hàng trả lại với kế toán công nợ.",en:"Reconcile rebates and returns with accounts receivable."},{time:"17:00",vi:"Báo cáo doanh số, rủi ro công nợ và kế hoạch thăm đại lý ngày mai.",en:"Report sales, credit risks and tomorrow's dealer visits."}],mistakes:{vi:["Xếp hạng đại lý chỉ theo doanh số mà bỏ qua điều kiện nợ quá hạn.","Tính thưởng trên doanh số gộp chưa trừ hàng trả lại.","Nhận quà, lại quả hoặc ưu ái riêng một đại lý, phá vỡ công bằng chính sách."],en:["Tiering dealers on volume only and ignoring the overdue condition.","Computing rebates on gross purchases before returns.","Accepting gifts or kickbacks or favoring one dealer, breaking policy fairness."]},career:[{vi:"Nhân viên kinh doanh đại lý",en:"Dealer sales representative"},{vi:"Chuyên viên kinh doanh kênh phân phối",en:"Channel sales executive"},{vi:"Giám sát kênh phân phối khu vực",en:"Area channel supervisor"},{vi:"Quản lý kênh phân phối toàn quốc",en:"National channel manager"}],glossary:[{term:"Rebate",vi:"Thưởng chiết khấu cuối kỳ dựa trên doanh số mua thuần và hạng đại lý.",en:"A period-end payment based on net purchases and dealer tier."},{term:"Credit limit",vi:"Hạn mức tín dụng: dư nợ tối đa đại lý được phép trước khi bị khóa đơn.",en:"The maximum balance a dealer may owe before orders are held."},{term:"Aging",vi:"Tuổi nợ: phân loại công nợ theo số ngày kể từ hạn thanh toán.",en:"Grouping receivables by days past the due date."},{term:"DSO",vi:"Số ngày thu tiền bình quân, đo tốc độ đại lý thanh toán.",en:"Days sales outstanding, measuring how fast dealers pay."},{term:"POSM",vi:"Vật phẩm hỗ trợ bán hàng tại điểm bán: kệ, bảng hiệu, bảng màu, tờ rơi.",en:"Point-of-sale materials: racks, signs, color cards and leaflets."}],quiz:[{q:{vi:"Đại lý mua 900 triệu, trả lại 50 triệu, hạng SILVER 2%. Thưởng chiết khấu là bao nhiêu?",en:"A dealer bought 900 million, returned 50 million and is SILVER at 2%. What is the rebate?"},options:{vi:["18 triệu","16 triệu","17 triệu","29,75 triệu"],en:["18 million","16 million","17 million","29.75 million"]},answer:2,explain:{vi:"(900 - 50) x 2% = 17 triệu; thưởng tính trên doanh số mua thuần.",en:"(900 - 50) x 2% = 17 million; rebates use net purchases."}},{q:{vi:"Theo chính sách trong bài, đại lý mua thuần 1600 triệu nhưng có nợ quá hạn 20 ngày được xếp hạng nào?",en:"Under the training policy, a dealer with 1600 million net purchases and debt 20 days overdue gets which tier?"},options:{vi:["SILVER","GOLD","STANDARD","Không xếp hạng"],en:["SILVER","GOLD","STANDARD","No tier"]},answer:0,explain:{vi:"GOLD yêu cầu không có nợ quá hạn; nợ quá hạn dưới 60 ngày và doanh số trên 800 triệu thì đạt SILVER.",en:"GOLD requires no overdue debt; under 60 days overdue with over 800 million qualifies for SILVER."}},{q:{vi:"Vì sao cần khóa đơn khi đại lý vượt hạn mức tín dụng?",en:"Why hold orders when a dealer exceeds the credit limit?"},options:{vi:["Để phạt đại lý","Để kiểm soát rủi ro nợ xấu và giữ công bằng chính sách với đại lý khác","Để giảm doanh số cuối kỳ","Vì kế toán yêu cầu không cần lý do"],en:["To punish the dealer","To control bad-debt risk and keep policy fair to other dealers","To lower period sales","Because accounting says so without reason"]},answer:1,explain:{vi:"Hạn mức tín dụng bảo vệ dòng tiền công ty; ngoại lệ phải được cấp có thẩm quyền phê duyệt.",en:"Credit limits protect company cash flow; exceptions need approval from the proper authority."}},{q:{vi:"Đại lý đề nghị chia lại 1% doanh số nếu bạn xếp họ hạng cao hơn. Bạn làm gì?",en:"A dealer offers you 1% of sales if you give them a higher tier. What do you do?"},options:{vi:["Nhận vì là quà cảm ơn","Nhận nhưng chuyển vào quỹ nhóm","Từ chối nhưng vẫn nâng hạng","Từ chối, giữ hạng đúng chính sách và báo cáo quản lý"],en:["Accept it as a thank-you","Accept it for the team fund","Refuse but upgrade anyway","Refuse, keep the correct tier and report to management"]},answer:3,explain:{vi:"Lại quả là hành vi tham nhũng trong doanh nghiệp, gây thiệt hại cho công ty và bất công với đại lý khác.",en:"A kickback is private-sector bribery that harms the company and is unfair to other dealers."}}],tools_en:["Distribution management system (DMS)","ERP / accounts receivable software","Dealer ordering app","Rebate reconciliation spreadsheet","Point-of-sale materials (POSM)"]}}})})(window.KKR);
